{
  "findings": [
    {
      "check_id": "CKV2_AWS_11",
      "title": "Ensure VPC flow logging is enabled in all VPCs",
      "resource": "aws_vpc.changeme_aws_vpc_simple",
      "severity": "MEDIUM",
      "explanation": "VPC flow logs are not enabled, which means network traffic within the VPC cannot be monitored. This can hinder incident investigation and detection of security issues."
    },
    {
      "check_id": "CKV2_AWS_12",
      "title": "Ensure the default security group of every VPC restricts all traffic",
      "resource": "aws_vpc.changeme_aws_vpc_simple",
      "severity": "MEDIUM",
      "explanation": "The default security group for the VPC is not explicitly configured to restrict all traffic. This could allow unintended network access."
    }
  ],
  "patched_code": "resource "aws_vpc" "changeme_aws_vpc_simple" {
  cidr_block = "10.1.0.0/16"

  enable_dns_support   = true
  enable_dns_hostnames = true

  flow_log {
    traffic_type = "ALL"
    log_destination_type = "cloud-watch-logs"
    log_group_name = "vpc-flow-logs"
  }
}

resource "aws_security_group" "default_restrict_all" {
  name        = "default-restrict-all"
  description = "Restrict all traffic"
  vpc_id      = aws_vpc.changeme_aws_vpc_simple.id

  ingress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = []
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = []
  }
}

resource "aws_security_group_rule" "default_ingress_rule" {
  type        = "ingress"
  from_port   = 0
  to_port     = 0
  protocol    = "-1"
  cidr_blocks = []
  security_group_id = aws_security_group.default_restrict_all.id
}

resource "aws_security_group_rule" "default_egress_rule" {
  type        = "egress"
  from_port   = 0
  to_port     = 0
  protocol    = "-1"
  cidr_blocks = []
  security_group_id = aws_security_group.default_restrict_all.id
}",
  "fix_summary": "Enabled VPC flow logs to monitor network traffic and added a security group to restrict all ingress and egress traffic for the VPC."
}
